// Parse Claude API response and Notion data
const newsResponse = $items('Claude: News Collector')[0]?.json || {};
const notionResponse = $items('Read Notion Published')[0]?.json || {};

// Extract news content from Claude response
let newsData = {};
if (newsResponse.content && Array.isArray(newsResponse.content)) {
  const textBlock = newsResponse.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      // Clean and parse JSON
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      newsData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse news data:', e);
      newsData = { error: 'Failed to parse', raw: textBlock.text };
    }
  }
}

// Extract published slugs from Notion
const publishedSlugs = [];
const publishedTitles = [];
if (notionResponse.results && Array.isArray(notionResponse.results)) {
  notionResponse.results.forEach(page => {
    // Extract slug
    const slugProp = page.properties?.Slug?.rich_text?.[0]?.plain_text;
    if (slugProp) publishedSlugs.push(slugProp.toLowerCase());

    // Extract title (property is 'Name' in Notion)
    const titleProp = page.properties?.Name?.title?.[0]?.plain_text;
    if (titleProp) publishedTitles.push(titleProp.toLowerCase());
  });
}

// Get content opportunities
const opportunities = newsData.content_opportunities || [];

return [{
  json: {
    news_data: newsData,
    published_slugs: publishedSlugs.join(', '),
    published_titles: publishedTitles.slice(0, 20).join(' | '),
    published_count: publishedSlugs.length,
    opportunities: opportunities,
    collection_date: newsData.collection_date || new Date().toISOString().split('T')[0]
  }
}];

// Parse topic selection from Claude response
const response = $input.first().json;
let topicData = {};

if (response.content && Array.isArray(response.content)) {
  const textBlock = response.content.find(block => block.type === 'text');
  if (textBlock?.text) {
    try {
      let jsonText = textBlock.text
        .replace(/^```json\s*/i, '')
        .replace(/^```\s*/i, '')
        .replace(/```$/i, '')
        .trim();
      const firstBrace = jsonText.indexOf('{');
      const lastBrace = jsonText.lastIndexOf('}');
      if (firstBrace !== -1 && lastBrace !== -1) {
        jsonText = jsonText.slice(firstBrace, lastBrace + 1);
      }
      topicData = JSON.parse(jsonText);
    } catch (e) {
      console.error('Failed to parse topic data:', e);
      throw new Error('Failed to parse topic selection: ' + e.message);
    }
  }
}

if (!topicData.selected_topic) {
  throw new Error('No topic selected by Claude');
}

const topic = topicData.selected_topic;

// Get previous node data
