// Strip markdown formatting from text (preserve emojis)
function stripMarkdown(text) {
  return text
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/__([^_]+)__/g, '$1')
    .replace(/_([^_]+)_/g, '$1')
    .replace(/~~([^~]+)~~/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .trim();
}

// Extract emoji from text if present at start
function extractEmoji(text) {
  const emojiRegex = /^([\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]+)\s*/u;
  const match = text.match(emojiRegex);
  return match ? match[1] : null;
}

// Convert markdown to Notion blocks
function markdownToNotionBlocks(markdown) {
  const lines = markdown.split('\n');
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const line = lines[i];

    // Skip H1
    if (line.startsWith('# ')) {
      i++;
      continue;
    }

    // H2 Heading
    if (line.startsWith('## ')) {
      blocks.push({
        object: 'block',
        type: 'heading_2',
        heading_2: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(line.slice(3)) } }]
        }
      });
      i++;
      continue;
    }

    // H3 Heading
    if (line.startsWith('### ')) {
      blocks.push({
        object: 'block',
        type: 'heading_3',
        heading_3: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(line.slice(4)) } }]
        }
      });
      i++;
      continue;
    }

    // H4 -> H3
    if (line.startsWith('#### ')) {
      blocks.push({
        object: 'block',
        type: 'heading_3',
        heading_3: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(line.slice(5)) } }]
        }
      });
      i++;
      continue;
    }

    // Bulleted list
    if (line.startsWith('- ') || line.startsWith('* ')) {
      blocks.push({
        object: 'block',
        type: 'bulleted_list_item',
        bulleted_list_item: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(line.slice(2)) } }]
        }
      });
      i++;
      continue;
    }

    // Numbered list
    if (/^\d+\.\s/.test(line)) {
      const content = line.replace(/^\d+\.\s/, '');
      blocks.push({
        object: 'block',
        type: 'numbered_list_item',
        numbered_list_item: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(content) } }]
        }
      });
      i++;
      continue;
    }

    // FAQ Question - multiple patterns supported
    if (/^\*\*Q[:.]/i.test(line) || /^Q[:.]/i.test(line)) {
      const question = stripMarkdown(line).replace(/^Q[:.] ?/i, 'Q: ');
      let answerLines = [];
      i++;

      // Collect answer lines until next question or section
      while (i < lines.length) {
        const nextLine = lines[i];
        if (/^\*\*Q[:.]/i.test(nextLine) || /^Q[:.]/i.test(nextLine) || nextLine.startsWith('#')) {
          break;
        }
        if (/^A[:.]/i.test(nextLine)) {
          answerLines.push(stripMarkdown(nextLine.replace(/^A[:.] ?/i, '')));
        } else if (nextLine.trim()) {
          answerLines.push(stripMarkdown(nextLine));
        }
        i++;
      }

      const answer = answerLines.join(' ').trim();

      blocks.push({
        object: 'block',
        type: 'toggle',
        toggle: {
          rich_text: [{ type: 'text', text: { content: question } }],
          children: [{
            object: 'block',
            type: 'paragraph',
            paragraph: {
              rich_text: [{ type: 'text', text: { content: answer || '답변을 확인해주세요.' } }]
            }
          }]
        }
      });
      continue;
    }

    // Callout with emoji extraction
    if (line.startsWith('> ')) {
      const content = stripMarkdown(line.slice(2));
      const emoji = extractEmoji(content) || '💡';
      const text = content.replace(/^[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]+\s*/u, '');

      blocks.push({
        object: 'block',
        type: 'callout',
        callout: {
          rich_text: [{ type: 'text', text: { content: text } }],
          icon: { emoji: emoji }
        }
      });
      i++;
      continue;
    }

    // Regular paragraph
    if (line.trim() !== '') {
      blocks.push({
        object: 'block',
        type: 'paragraph',
        paragraph: {
          rich_text: [{ type: 'text', text: { content: stripMarkdown(line) } }]
        }
      });
    }

    i++;
  }

  return blocks;
}

