// Blog Content Validator for Korean
const blog = $input.first().json;
const markdown = blog.content_markdown || '';
const blocks = blog.notion_blocks || [];

const errors = [];
const warnings = [];
const checks = {
  content_structure: { passed: 0, failed: 0, details: [] },
  seo: { passed: 0, failed: 0, details: [] },
  notion_blocks: { passed: 0, failed: 0, details: [] },
  readability: { passed: 0, failed: 0, details: [] },
  metadata: { passed: 0, failed: 0, details: [] }
};

// Helper functions
const countPattern = (text, pattern) => (text.match(pattern) || []).length;
const hasPattern = (text, pattern) => pattern.test(text);

// 1. Content Structure Checks
// 1.1 Word count (1500-2500)
const wordCount = blog.word_count || 0;
if (wordCount >= 1500 && wordCount <= 2500) {
  checks.content_structure.passed++;
  checks.content_structure.details.push({ item: 'word_count', status: 'pass', value: wordCount });
} else if (wordCount >= 1000) {
  checks.content_structure.passed++;
  warnings.push(`Word count ${wordCount} is outside ideal range (1500-2500)`);
  checks.content_structure.details.push({ item: 'word_count', status: 'warn', value: wordCount });
} else {
  checks.content_structure.failed++;
  errors.push(`Word count ${wordCount} is too low (min 1000)`);
  checks.content_structure.details.push({ item: 'word_count', status: 'fail', value: wordCount });
}

// 1.2 H1 count (exactly 1)
const h1Count = countPattern(markdown, /^# [^#]/gm);
if (h1Count === 1) {
  checks.content_structure.passed++;
} else {
  checks.content_structure.failed++;
  errors.push(`H1 count: ${h1Count} (expected 1)`);
}

// 1.3 H2 count (3-5)
const h2Count = countPattern(markdown, /^## [^#]/gm);
if (h2Count >= 3 && h2Count <= 7) {
  checks.content_structure.passed++;
} else if (h2Count >= 2) {
  checks.content_structure.passed++;
  warnings.push(`H2 count: ${h2Count} (ideal: 3-5)`);
} else {
  checks.content_structure.failed++;
  errors.push(`H2 count: ${h2Count} (min 2)`);
}

// 1.4 Conclusion section
const hasConclusion = /결론|마무리|정리|conclusion/i.test(markdown);
if (hasConclusion) {
  checks.content_structure.passed++;
} else {
  warnings.push('No conclusion section detected');
}

// 1.5 FAQ section
const faqCount = countPattern(markdown, /\*\*Q[:.]/gi) + countPattern(markdown, /^Q[:.]/gim);
if (faqCount >= 3) {
  checks.content_structure.passed++;
} else if (faqCount >= 1) {
  checks.content_structure.passed++;
  warnings.push(`FAQ count: ${faqCount} (recommended: 3-5)`);
} else {
  warnings.push('No FAQ section detected');
}

// 1.6 CTA (RemitBuddy mention)
const hasRemitBuddy = /remitbuddy|레밋버디/i.test(markdown);
if (hasRemitBuddy) {
  checks.content_structure.passed++;
} else {
  checks.content_structure.failed++;
  errors.push('No RemitBuddy CTA found');
}

// 2. SEO Checks
const primaryKeyword = blog.primary_keyword || '';
const title = blog.title || '';

// 2.1 Keyword in title
if (primaryKeyword && title.toLowerCase().includes(primaryKeyword.toLowerCase())) {
  checks.seo.passed++;
} else if (primaryKeyword) {
  checks.seo.failed++;
  errors.push(`Primary keyword "${primaryKeyword}" not in title`);
}

// 2.2 Keyword in first paragraph
const firstPara = markdown.split('\n\n')[1] || '';
if (primaryKeyword && firstPara.toLowerCase().includes(primaryKeyword.toLowerCase())) {
  checks.seo.passed++;
} else if (primaryKeyword) {
  warnings.push('Primary keyword not in first paragraph');
}

// 2.3 Meta description length
const metaDesc = blog.meta_description || '';
if (metaDesc.length >= 100 && metaDesc.length <= 160) {
  checks.seo.passed++;
} else {
  checks.seo.failed++;
  errors.push(`Meta description length: ${metaDesc.length} (ideal: 100-160)`);
}

// 2.4 Title length
if (title.length <= 60) {
  checks.seo.passed++;
} else {
  warnings.push(`Title length: ${title.length} (max 60)`);
}

// 2.5 Slug format
const slug = blog.slug || '';
if (/^[a-z0-9-]+$/.test(slug)) {
  checks.seo.passed++;
} else {
  checks.seo.failed++;
  errors.push(`Invalid slug format: ${slug}`);
}

// 3. Notion Blocks Checks
// 3.1 Has lists
const hasBulletList = blocks.some(b => b.type === 'bulleted_list_item');
const hasNumberedList = blocks.some(b => b.type === 'numbered_list_item');
if (hasBulletList || hasNumberedList) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No lists found in content');
}

// 3.2 Has callout
const hasCallout = blocks.some(b => b.type === 'callout');
if (hasCallout) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No callout blocks - consider adding for important tips');
}

// 3.3 Has toggle (FAQ)
const hasToggle = blocks.some(b => b.type === 'toggle');
if (hasToggle) {
  checks.notion_blocks.passed++;
} else if (faqCount > 0) {
  checks.notion_blocks.failed++;
  errors.push('FAQ detected but no toggle blocks created');
}

// 3.4 Has emoji
const emojiRegex = /[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/u;
const hasEmoji = emojiRegex.test(markdown);
if (hasEmoji) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No emojis found - consider adding for better readability');
}

// 4. Readability Checks
// 4.1 Short paragraphs (check for very long paragraphs)
const paragraphs = markdown.split(/\n\n+/);
const longParas = paragraphs.filter(p => p.split(/[.!?]/).length > 6);
if (longParas.length === 0) {
  checks.readability.passed++;
} else {
  warnings.push(`${longParas.length} paragraphs may be too long`);
}

// 4.2 Korean honorifics (존댓말)
const hasHonorifics = /습니다|세요|어요|해요/g.test(markdown);
if (hasHonorifics) {
  checks.readability.passed++;
} else {
  warnings.push('No Korean honorifics detected');
}

// 4.3 English terms with Korean (영어 병기)
const hasBilingual = /\([A-Za-z]+\)|\([A-Za-z]+ [A-Za-z]+\)/.test(markdown);
if (hasBilingual) {
  checks.readability.passed++;
} else {
  warnings.push('Consider adding English terms in parentheses for clarity');
}

// 4.4 Has numbers/examples
const hasNumbers = /\d{1,3}(,\d{3})*원|\d+%|\$\d+/.test(markdown);
if (hasNumbers) {
  checks.readability.passed++;
} else {
  warnings.push('No numerical examples found');
}

// 5. Metadata Checks
// 5.1 Tags count
const tags = blog.tags || [];
if (tags.length >= 3 && tags.length <= 5) {
  checks.metadata.passed++;
} else {
  warnings.push(`Tags count: ${tags.length} (ideal: 3-5)`);
}

// 5.2 Category exists
if (blog.category) {
  checks.metadata.passed++;
} else {
  checks.metadata.failed++;
  errors.push('No category specified');
}

// Calculate score
const totalPassed = Object.values(checks).reduce((sum, c) => sum + c.passed, 0);
const totalFailed = Object.values(checks).reduce((sum, c) => sum + c.failed, 0);
const totalChecks = totalPassed + totalFailed;
const score = totalChecks > 0 ? Math.round((totalPassed / totalChecks) * 100) : 0;

const validation = {
  language: 'ko',
  validation_passed: errors.length === 0,
  score: score,
  total_checks: totalChecks,
  checks: checks,
  errors: errors,
  warnings: warnings,
  summary: errors.length === 0 
    ? `✅ Validation passed (${score}% score, ${warnings.length} warnings)`
    : `❌ Validation failed: ${errors.length} errors`
};

return [{ json: { ...blog, validation } }];

// Blog Content Validator for English
const blog = $input.first().json;
const markdown = blog.content_markdown || '';
const blocks = blog.notion_blocks || [];

const errors = [];
const warnings = [];
const checks = {
  content_structure: { passed: 0, failed: 0, details: [] },
  seo: { passed: 0, failed: 0, details: [] },
  notion_blocks: { passed: 0, failed: 0, details: [] },
  readability: { passed: 0, failed: 0, details: [] },
  metadata: { passed: 0, failed: 0, details: [] }
};

const countPattern = (text, pattern) => (text.match(pattern) || []).length;

// 1. Content Structure Checks
const wordCount = blog.word_count || 0;
if (wordCount >= 1500 && wordCount <= 2500) {
  checks.content_structure.passed++;
} else if (wordCount >= 1000) {
  checks.content_structure.passed++;
  warnings.push(`Word count ${wordCount} outside ideal range (1500-2500)`);
} else {
  checks.content_structure.failed++;
  errors.push(`Word count ${wordCount} too low (min 1000)`);
}

const h1Count = countPattern(markdown, /^# [^#]/gm);
if (h1Count === 1) {
  checks.content_structure.passed++;
} else {
  checks.content_structure.failed++;
  errors.push(`H1 count: ${h1Count} (expected 1)`);
}

const h2Count = countPattern(markdown, /^## [^#]/gm);
if (h2Count >= 3 && h2Count <= 7) {
  checks.content_structure.passed++;
} else if (h2Count >= 2) {
  checks.content_structure.passed++;
  warnings.push(`H2 count: ${h2Count} (ideal: 3-5)`);
} else {
  checks.content_structure.failed++;
  errors.push(`H2 count: ${h2Count} (min 2)`);
}

const hasConclusion = /conclusion|summary|final thoughts|wrap up/i.test(markdown);
if (hasConclusion) {
  checks.content_structure.passed++;
} else {
  warnings.push('No conclusion section detected');
}

const faqCount = countPattern(markdown, /\*\*Q[:.]/gi) + countPattern(markdown, /^Q[:.]/gim);
if (faqCount >= 3) {
  checks.content_structure.passed++;
} else if (faqCount >= 1) {
  checks.content_structure.passed++;
  warnings.push(`FAQ count: ${faqCount} (recommended: 3-5)`);
} else {
  warnings.push('No FAQ section detected');
}

const hasRemitBuddy = /remitbuddy/i.test(markdown);
if (hasRemitBuddy) {
  checks.content_structure.passed++;
} else {
  checks.content_structure.failed++;
  errors.push('No RemitBuddy CTA found');
}

// 2. SEO Checks
const primaryKeyword = blog.primary_keyword || '';
const title = blog.title || '';

if (primaryKeyword && title.toLowerCase().includes(primaryKeyword.toLowerCase())) {
  checks.seo.passed++;
} else if (primaryKeyword) {
  checks.seo.failed++;
  errors.push(`Primary keyword "${primaryKeyword}" not in title`);
}

const firstPara = markdown.split('\n\n')[1] || '';
if (primaryKeyword && firstPara.toLowerCase().includes(primaryKeyword.toLowerCase())) {
  checks.seo.passed++;
} else if (primaryKeyword) {
  warnings.push('Primary keyword not in first paragraph');
}

const metaDesc = blog.meta_description || '';
if (metaDesc.length >= 100 && metaDesc.length <= 160) {
  checks.seo.passed++;
} else {
  checks.seo.failed++;
  errors.push(`Meta description length: ${metaDesc.length} (ideal: 100-160)`);
}

if (title.length <= 60) {
  checks.seo.passed++;
} else {
  warnings.push(`Title length: ${title.length} (max 60)`);
}

const slug = blog.slug || '';
if (/^[a-z0-9-]+$/.test(slug)) {
  checks.seo.passed++;
} else {
  checks.seo.failed++;
  errors.push(`Invalid slug format: ${slug}`);
}

// 3. Notion Blocks Checks
const hasBulletList = blocks.some(b => b.type === 'bulleted_list_item');
const hasNumberedList = blocks.some(b => b.type === 'numbered_list_item');
if (hasBulletList || hasNumberedList) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No lists found in content');
}

const hasCallout = blocks.some(b => b.type === 'callout');
if (hasCallout) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No callout blocks');
}

const hasToggle = blocks.some(b => b.type === 'toggle');
if (hasToggle) {
  checks.notion_blocks.passed++;
} else if (faqCount > 0) {
  checks.notion_blocks.failed++;
  errors.push('FAQ detected but no toggle blocks created');
}

const emojiRegex = /[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/u;
const hasEmoji = emojiRegex.test(markdown);
if (hasEmoji) {
  checks.notion_blocks.passed++;
} else {
  warnings.push('No emojis found');
}

// 4. Readability Checks
const sentences = markdown.split(/[.!?]+/).filter(s => s.trim());
const avgWordsPerSentence = sentences.length > 0 
  ? Math.round(wordCount / sentences.length) : 0;
if (avgWordsPerSentence <= 20) {
  checks.readability.passed++;
} else {
  warnings.push(`Avg sentence length: ${avgWordsPerSentence} words (ideal: 15-20)`);
}

const hasNumbers = /\$\d+|\d+%|\d{1,3}(,\d{3})*/.test(markdown);
if (hasNumbers) {
  checks.readability.passed++;
} else {
  warnings.push('No numerical examples found');
}

// 5. Metadata Checks
const tags = blog.tags || [];
if (tags.length >= 3 && tags.length <= 5) {
  checks.metadata.passed++;
} else {
  warnings.push(`Tags count: ${tags.length} (ideal: 3-5)`);
}

if (blog.category) {
  checks.metadata.passed++;
} else {
  checks.metadata.failed++;
  errors.push('No category specified');
}

const totalPassed = Object.values(checks).reduce((sum, c) => sum + c.passed, 0);
const totalFailed = Object.values(checks).reduce((sum, c) => sum + c.failed, 0);
const totalChecks = totalPassed + totalFailed;
const score = totalChecks > 0 ? Math.round((totalPassed / totalChecks) * 100) : 0;

const validation = {
  language: 'en',
  validation_passed: errors.length === 0,
  score: score,
  total_checks: totalChecks,
  checks: checks,
  errors: errors,
  warnings: warnings,
  summary: errors.length === 0 
    ? `✅ Validation passed (${score}% score, ${warnings.length} warnings)`
    : `❌ Validation failed: ${errors.length} errors`
};

return [{ json: { ...blog, validation } }];

