// Append remaining blocks to Korean Notion page
const uploadResult = $input.first().json;
const blogData = $items('Parse & Convert KO Blog')[0]?.json || {};

const pageId = uploadResult.id;
const remainingChunks = blogData.remaining_chunks || [];

if (!pageId || remainingChunks.length === 0) {
  return [{ json: { ...uploadResult, blocks_appended: 0 } }];
}

const notionApiKey = 'ntn_H74281941305Hc34HPjs7eEz4THB9LUwLb4h6oFYHQL5qI';

let totalAppended = 0;
for (const chunk of remainingChunks) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'PATCH',
      url: `https://api.notion.com/v1/blocks/${pageId}/children`,
      headers: {
        'Authorization': `Bearer ${notionApiKey}`,
        'Notion-Version': '2022-06-28',
        'Content-Type': 'application/json'
      },
      body: { children: chunk },
      json: true
    });
    if (response) {
      totalAppended += chunk.length;
    }
  } catch (e) {
    console.error('Failed to append blocks:', e.message);
  }
}

return [{ json: { ...uploadResult, blocks_appended: totalAppended, total_blocks: blogData.total_blocks } }];

