return [{ json: { ...uploadResult, blocks_appended: totalAppended, total_blocks: blogData.total_blocks } }];

// Compile final report with validation results
const koUpload = $items('Append Remaining KO')[0]?.json || {};
const enUpload = $items('Append Remaining EN')[0]?.json || {};
